const page = document.getElementById("page");
const nav = document.getElementById("mainNav");
const breadcrumb = document.getElementById("breadcrumb");
const searchInput = document.getElementById("siteSearch");
const suggestions = document.getElementById("searchSuggestions");
const sidebar = document.getElementById("sidebar");
const overlay = document.getElementById("overlay");

function slugify(text) { return text.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""); }
function escapeHtml(text = "") { return String(text).replace(/[&<>\"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#039;'}[m])); }

function getRouteParts() {
  const raw = (location.hash || "#/home").replace(/^#\/?/, "");
  return raw.split("/").filter(Boolean);
}
function makeUrl(slug, section, anchor) { return `#/piece/${slug}/${section}${anchor ? `/${anchor}` : ""}`; }
function navigateTo(url) {
  hideSuggestions();
  searchInput.value = "";
  if (location.hash === url) route(); else location.hash = url;
}

function buildNav() {
  let html = `<div class="nav-section"><a class="nav-link" href="#/home">🏠 Home</a><a class="nav-link" href="#/strategy">🧠 Answer strategy</a></div>`;
  html += `<div class="nav-section"><div class="nav-section-title">Pieces</div>`;
  Object.entries(pieces).forEach(([slug, piece]) => {
    html += `<a class="nav-link" href="${makeUrl(slug, "summary")}">${piece.icon} ${piece.title}</a>`;
    html += `<a class="nav-link small" href="${makeUrl(slug, "text")}">Original text</a>`;
    html += `<a class="nav-link small" href="${makeUrl(slug, "summary")}">Summary & analysis</a>`;
    html += `<a class="nav-link small" href="${makeUrl(slug, "questions")}">Question pool</a>`;
  });
  html += `</div>`;
  nav.innerHTML = html;
}
function setActiveNav() {
  const parts = getRouteParts();
  const baseHash = parts[0] === "piece" ? `#/piece/${parts[1]}/${parts[2] || "summary"}` : `#/${parts[0] || "home"}`;
  document.querySelectorAll(".nav-link").forEach(a => a.classList.toggle("active", a.getAttribute("href") === baseHash));
}
function titleBlock(piece, sectionName) { return `<div class="page-title"><span class="eyebrow">${escapeHtml(piece.author)}</span><h2>${piece.icon} ${escapeHtml(piece.title)}</h2><p>${escapeHtml(sectionName)}</p></div>`; }
function sectionTabs(slug, active) {
  const tabs = [["text","Original text"],["summary","Summary & analysis"],["questions","Question pool"]];
  return `<div class="card-actions tabs">${tabs.map(([key,label]) => `<a class="button ${key===active?'primary':'ghost'}" href="${makeUrl(slug,key)}">${label}</a>`).join("")}</div>`;
}
function renderHome() {
  const template = document.getElementById("homeTemplate").content.cloneNode(true);
  page.innerHTML = ""; page.appendChild(template);
  document.getElementById("homeCards").innerHTML = Object.entries(pieces).map(([slug, piece]) => `
    <article class="card" id="card-${slug}">
      <span class="tag">${escapeHtml(piece.author)}</span>
      <h3>${piece.icon} ${escapeHtml(piece.title)}</h3>
      <p>${escapeHtml(piece.short)}</p>
      <div class="card-actions"><a class="button ghost" href="${makeUrl(slug,"summary")}">Summary</a><a class="button ghost" href="${makeUrl(slug,"questions")}">Questions</a><a class="button ghost" href="${makeUrl(slug,"text")}">Text</a></div>
    </article>`).join("");
  breadcrumb.textContent = "Home";
}
function renderPiece(slug, section, anchor) {
  const piece = pieces[slug]; if (!piece) return renderHome();
  breadcrumb.textContent = `${piece.title} / ${section || "summary"}`;
  if (section === "text") return renderText(piece, slug, anchor);
  if (section === "questions") return renderQuestions(piece, slug, anchor);
  return renderSummary(piece, slug, anchor);
}
function renderText(piece, slug) {
  const body = piece.publicDomain
    ? `<article class="text-page"><div class="poem">${escapeHtml(piece.text)}</div></article>`
    : `<article class="text-page empty-text"><h3>${escapeHtml(piece.title)}</h3></article>`;
  page.innerHTML = titleBlock(piece, "Original text") + sectionTabs(slug, "text") + body;
}
function listItems(items) { return items.map(x => `<li>${escapeHtml(x)}</li>`).join(""); }
function pairItems(items) { return items.map(([name, desc]) => `<li><strong>${escapeHtml(name)}:</strong> ${escapeHtml(desc)}</li>`).join(""); }
function accordion(title, inner, id, open=true) { return `<details id="${id}" ${open?"open":""}><summary>${escapeHtml(title)}</summary><div class="details-body"><ul>${inner}</ul></div></details>`; }
function renderSummary(piece, slug) {
  const s = piece.summary;
  page.innerHTML = titleBlock(piece, "Full summary and deep analysis") + sectionTabs(slug, "summary") + `
    <section class="panel" id="overview"><h3>Overview</h3><p>${escapeHtml(s.overview)}</p></section>
    ${accordion("Plot timeline", listItems(s.plot), "plot-timeline")}
    ${accordion("Characters", pairItems(s.characters), "characters")}
    ${accordion("Themes", pairItems(s.themes), "themes")}
    ${accordion("Symbols and motifs", pairItems(s.symbols), "symbols")}
    ${accordion("Deep analysis", pairItems(s.deepAnalysis), "deep-analysis")}
    ${accordion("Question-pool integrated analysis", pairItems(s.questionAnalysis), "question-pool-integrated-analysis")}
    ${accordion("Exam tips", listItems(s.examTips), "exam-tips")}`;
}
function renderQuestions(piece, slug) {
  function defaultExpectedTitle(piece) {
  if (piece.title === "Rules of the Game") return "What your answer needs:";
  if (piece.title === "The Road Not Taken") return "What your answer should include:";
  if (piece.title === "Mr. Know-All") return "Your answer must include:";
  return "What your answer must include:";
  }
  
  function renderExpectedBullet(bullet) {
    if (typeof bullet === "string") {
      return `<li>${escapeHtml(bullet)}</li>`;
    }
  
    if (bullet && typeof bullet === "object") {
      const children = Array.isArray(bullet.children) && bullet.children.length
        ? `<ul class="nested-expected-list">${bullet.children.map(child => `<li>${escapeHtml(child)}</li>`).join("")}</ul>`
        : "";
  
      return `<li><span>${escapeHtml(bullet.text || "")}</span>${children}</li>`;
    }
  
    return "";
  }
  
  function renderExpectedSections(item, piece) {
    if (Array.isArray(item.sections)) {
      return item.sections.map(section => `
        <div class="expected-section">
          <div class="expected-title">${escapeHtml(section.title)}</div>
          ${Array.isArray(section.bullets) && section.bullets.length
            ? `<ul>${section.bullets.map(renderExpectedBullet).join("")}</ul>`
            : ""}
        </div>
      `).join("");
    }
  
    return `
      <div class="expected-section">
        <div class="expected-title">${escapeHtml(item.expectedTitle || defaultExpectedTitle(piece))}</div>
        <ul>${(item.e || []).map(renderExpectedBullet).join("")}</ul>
      </div>
    `;
  }
  
  function renderQuestions(piece, slug) {
    page.innerHTML = titleBlock(piece, `Question pool: ${piece.questions.length} questions`) + sectionTabs(slug, "questions") + `
      <div class="notice"><strong>How to use:</strong> practice each question with one clear claim, at least one story example, and an explanation of why the example proves your answer.</div>
      ${piece.questions.map((item, i) => `
        <article class="question-card" id="q-${i + 1}">
          <span class="tag">Question ${i + 1}</span>
          <h3>${escapeHtml(item.q)}</h3>
          <div class="expected">
            ${renderExpectedSections(item, piece)}
          </div>
        </article>
      `).join("")}
    `;
  }
}
function renderStrategy() {
  breadcrumb.textContent = "Answer strategy";
  page.innerHTML = `<div class="page-title"><span class="eyebrow">Exam skills</span><h2>${strategyContent.title}</h2><p>${strategyContent.subtitle}</p></div>
  ${strategyContent.blocks.map(([h,p],i) => `<section class="panel" id="strategy-${i+1}"><h3>${h}</h3><p>${p}</p></section>`).join("")}
  <section class="panel"><h3>Fast answer template</h3><p><strong>Claim:</strong> I think ___ because ___.<br><strong>Evidence:</strong> In the text, ___.<br><strong>Explanation:</strong> This shows that ___.<br><strong>Conclusion:</strong> Therefore, ___.</p></section>`;
}
function route() {
  const parts = getRouteParts();
  const anchor = parts[3];
  if (parts[0] === "piece") renderPiece(parts[1], parts[2] || "summary", anchor);
  else if (parts[0] === "strategy") renderStrategy();
  else renderHome();
  setActiveNav(); closeMobileNav();
  setTimeout(() => {
    if (anchor) {
      const el = document.getElementById(anchor);
      if (el) { if (el.tagName.toLowerCase() === "details") el.open = true; el.scrollIntoView({behavior:"smooth", block:"start"}); return; }
    }
    window.scrollTo({top:0, behavior:"auto"});
  }, 30);
}
function buildSearchIndex() {
  const index = [];
  Object.entries(pieces).forEach(([slug, piece]) => {
    index.push({title: piece.title, type:"Piece", url:makeUrl(slug,"summary"), text:`${piece.title} ${piece.author} ${piece.short}`});
    index.push({title:`${piece.title}: Overview`, type:"Summary", url:makeUrl(slug,"summary","overview"), text:piece.summary.overview});
    const groups = {"plot":"Plot timeline", "characters":"Characters", "themes":"Themes", "symbols":"Symbols and motifs", "deepAnalysis":"Deep analysis", "questionAnalysis":"Question-pool integrated analysis", "examTips":"Exam tips"};
    Object.entries(groups).forEach(([key,label]) => {
      const value = piece.summary[key]; const text = Array.isArray(value) ? value.flat(2).join(" ") : String(value);
      index.push({title:`${piece.title}: ${label}`, type:"Analysis", url:makeUrl(slug,"summary",slugify(label)), text});
    });
    piece.questions.forEach((item, i) => index.push({title:`${piece.title}: Question ${i+1}`, type:"Question", url:makeUrl(slug,"questions",`q-${i+1}`), text:`${item.q} ${item.e.join(" ")}`}));
    if (piece.text) index.push({title:`${piece.title}: Original text`, type:"Text", url:makeUrl(slug,"text"), text:piece.text});
  });
  strategyContent.blocks.forEach(([h,p],i) => index.push({title:h, type:"Strategy", url:`#/strategy/${`strategy-${i+1}`}`, text:p}));
  return index;
}
const searchIndex = buildSearchIndex();
function hideSuggestions(){ suggestions.hidden = true; suggestions.innerHTML = ""; }
function doSearch(query) {
  const q = query.trim().toLowerCase();
  if (q.length < 2) return hideSuggestions();
  const words = q.split(/\s+/).filter(Boolean);
  const results = searchIndex.map(item => {
    const hay = `${item.title} ${item.text}`.toLowerCase();
    let score = 0;
    if (item.title.toLowerCase().includes(q)) score += 8;
    words.forEach(w => { if (hay.includes(w)) score += 1; if (item.title.toLowerCase().includes(w)) score += 2; });
    return {...item, score};
  }).filter(r => r.score > 0).sort((a,b) => b.score - a.score).slice(0, 8);
  if (!results.length) return hideSuggestions();
  suggestions.hidden = false;
  suggestions.innerHTML = results.map(r => `<button class="suggestion-item" type="button" data-url="${r.url}"><strong>${escapeHtml(r.title)}</strong><span>${escapeHtml(r.type)} - ${escapeHtml(snippet(r.text, q))}</span></button>`).join("");
}
function snippet(text, q) {
  const clean = String(text).replace(/\s+/g, " "); const idx = clean.toLowerCase().indexOf(q.toLowerCase());
  if (idx === -1) return clean.slice(0, 100) + (clean.length > 100 ? "..." : "");
  return (idx > 28 ? "..." : "") + clean.slice(Math.max(0, idx-28), idx+90) + "...";
}
function closeMobileNav(){ sidebar.classList.remove("open"); overlay.classList.remove("show"); }
function openMobileNav(){ sidebar.classList.add("open"); overlay.classList.add("show"); }

document.getElementById("openSidebar").addEventListener("click", openMobileNav);
document.getElementById("closeSidebar").addEventListener("click", closeMobileNav);
overlay.addEventListener("click", closeMobileNav);
searchInput.addEventListener("input", e => doSearch(e.target.value));
searchInput.addEventListener("keydown", e => { if (e.key === "Escape") hideSuggestions(); });
suggestions.addEventListener("click", e => { const btn = e.target.closest(".suggestion-item"); if (btn) navigateTo(btn.dataset.url); });
document.addEventListener("click", e => { if (!e.target.closest(".search-box")) hideSuggestions(); });
document.getElementById("themeToggle").addEventListener("click", () => { const next = document.documentElement.dataset.theme === "dark" ? "light" : "dark"; document.documentElement.dataset.theme = next; localStorage.setItem("theme", next); });
window.addEventListener("hashchange", route);
const savedTheme = localStorage.getItem("theme"); if (savedTheme) document.documentElement.dataset.theme = savedTheme;
buildNav(); route();
